import{_ as e,o as a,c as r,a5 as l}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"每周复盘模板","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/weekly-review.zh.md","filePath":"public/downloads/worksheets/weekly-review.zh.md","lastUpdated":1795488252000}'),i={name:"public/downloads/worksheets/weekly-review.zh.md"};function h(d,t,o,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="每周复盘模板" tabindex="-1">每周复盘模板 <a class="header-anchor" href="#每周复盘模板" aria-label="Permalink to &quot;每周复盘模板&quot;">​</a></h1><p>复盘不是给自己判分，而是为下一周留下一个更准确的起点。每周预留 20 分钟，先看证据，再解释原因，最后只改变一个变量。不要写入密码、客户资料、医疗隐私或未获授权的第三方信息。</p><h2 id="weekly-review-—-yyyy-www" tabindex="-1">Weekly Review — YYYY-Www <a class="header-anchor" href="#weekly-review-—-yyyy-www" aria-label="Permalink to &quot;Weekly Review — YYYY-Www&quot;">​</a></h2><h3 id="本周主问题" tabindex="-1">本周主问题 <a class="header-anchor" href="#本周主问题" aria-label="Permalink to &quot;本周主问题&quot;">​</a></h3><ul><li>目标：</li><li>本周只回答一个问题：</li><li>完成标准：</li><li>约束（时间、精力、责任）：</li></ul><h3 id="证据清单" tabindex="-1">证据清单 <a class="header-anchor" href="#证据清单" aria-label="Permalink to &quot;证据清单&quot;">​</a></h3><ul><li>完成了什么：</li><li>作品/录音/测试位置：</li><li>首版、辅助版、延迟复测位置：</li><li>外部读者/用户反馈：</li></ul><table tabindex="0"><thead><tr><th>证据</th><th>它说明了什么</th><th>仍然不能说明什么</th></tr></thead><tbody><tr><td></td><td></td><td></td></tr></tbody></table><h3 id="四项检查-0–2" tabindex="-1">四项检查（0–2） <a class="header-anchor" href="#四项检查-0–2" aria-label="Permalink to &quot;四项检查（0–2）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">分数</th><th>评分理由与证据</th></tr></thead><tbody><tr><td>完成：任务是否完成</td><td style="text-align:right;"></td><td></td></tr><tr><td>质量：是否达到标准</td><td style="text-align:right;"></td><td></td></tr><tr><td>保持：几天后还能复现</td><td style="text-align:right;"></td><td></td></tr><tr><td>迁移：换条件还能使用</td><td style="text-align:right;"></td><td></td></tr></tbody></table><h3 id="错误与原因" tabindex="-1">错误与原因 <a class="header-anchor" href="#错误与原因" aria-label="Permalink to &quot;错误与原因&quot;">​</a></h3><table tabindex="0"><thead><tr><th>错误/阻碍</th><th>证据</th><th>可能原因</th><th>下一次测试</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="精力与恢复" tabindex="-1">精力与恢复 <a class="header-anchor" href="#精力与恢复" aria-label="Permalink to &quot;精力与恢复&quot;">​</a></h3><ul><li>睡眠/压力对表现的影响：</li><li>哪个安排不可持续：</li><li>本周需要暂停或求助的事项：</li></ul><h3 id="下周只改一个变量" tabindex="-1">下周只改一个变量 <a class="header-anchor" href="#下周只改一个变量" aria-label="Permalink to &quot;下周只改一个变量&quot;">​</a></h3><ul><li>保留：</li><li>停止：</li><li>调整：</li><li>最重要任务及完成标准：</li><li>下次复查日期：</li></ul><h3 id="写回状态" tabindex="-1">写回状态 <a class="header-anchor" href="#写回状态" aria-label="Permalink to &quot;写回状态&quot;">​</a></h3><p>复盘只写回真正改变决定的内容，不要把同一段话复制到四个文件。按任务选择职责：</p><ul><li><a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">证据链模板</a>：保存基线、即时表现、延迟保持和迁移的比较；</li><li><a href="https://byoungd.github.io/up/templates/rhythm-ledger" target="_blank" rel="noreferrer">节律账本</a>：保存本周节奏、容量版本、反复阻力和下周要改变的条件；</li><li><a href="https://byoungd.github.io/up/templates/learning-state" target="_blank" rel="noreferrer">学习状态</a>：保存跨会话交接、未确认事实、边界和下一项最小任务；</li><li><a href="https://byoungd.github.io/up/templates/90-day-cycle" target="_blank" rel="noreferrer">九十日行动总表</a>：保存阶段门槛、十二周主问题和周期方向。</li></ul><p>证据链已更新：是 / 否 / 不适用<br> 节律账本已更新：是 / 否 / 不适用<br> 学习状态文件已更新：是 / 否<br> 九十日行动总表已更新：是 / 否 / 不适用<br> 下一项最小任务的证据位置：</p><h2 id="写回后的交接入口" tabindex="-1">写回后的交接入口 <a class="header-anchor" href="#写回后的交接入口" aria-label="Permalink to &quot;写回后的交接入口&quot;">​</a></h2><p>完成复盘后，按职责打开需要更新的文件： <a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">证据链模板</a> 负责比较四个时间点；<a href="https://byoungd.github.io/up/templates/rhythm-ledger" target="_blank" rel="noreferrer">节律账本</a> 负责记录本周节奏；<a href="https://byoungd.github.io/up/templates/learning-state" target="_blank" rel="noreferrer">学习状态</a> 负责跨会话交接；<a href="https://byoungd.github.io/up/templates/90-day-cycle" target="_blank" rel="noreferrer">九十日行动总表</a> 负责周期门槛。</p><p>不要因为一周状态差就重写整套计划。先区分偶发波动与连续三次出现的模式；连续出现时，优先改变环境、任务大小或支持网络。</p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/weekly-review" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-01。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',25)])])}const c=e(i,[["render",h]]);export{p as __pageData,c as default};
